            .onNodeWithText(text = "Why is this step required?")
            .performScrollTo()
            .performClick()
        verify(exactly = 1) {
            viewModel.trySendAction(SetupBrowserAutofillAction.WhyIsThisStepRequiredClick)
        }
    }

    @Test
